	@Test
	void spatialLookupsRequireWktDatatypeAcrossUpdatesAndContexts() throws Exception {
		var repository = mappedGeometryRepository(new RecordingIndex(),
				TupleFunctionEvaluationMode.NATIVE, new TupleFunctionRegistry());
		try (var connection = repository.getConnection()) {
			var origin = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
			var plain = Values.literal(origin.getLabel());
			var language = Values.literal(origin.getLabel(), "en");
			var g1 = Values.iri("urn:g1");
			var g2 = Values.iri("urn:g2");
			connection.add(NEAR, SOURCE_LOCATION, plain, g1);
			connection.add(FAR, SOURCE_LOCATION, language, g2);
			String pattern = """
					VALUES ?origin { 'POINT(0 0)'^^geo:wktLiteral }
					?s <urn:location> ?wkt FILTER(geof:sfIntersects(?origin, ?wkt))
					""";
			String merged = "FROM <urn:g1> FROM <urn:g2> WHERE {" + pattern + "}";
			assertSubjects(connection, merged, List.of());
			connection.add(NEAR, SOURCE_LOCATION, origin, g1);
			assertSubjects(connection, merged, List.of(NEAR));
			assertSubjects(connection, "WHERE { GRAPH <urn:g1> {" + pattern + "} }", List.of(NEAR));
			connection.remove(NEAR, SOURCE_LOCATION, plain, g1);
			assertSubjects(connection, merged, List.of(NEAR));
			connection.add(NEAR, SOURCE_LOCATION, plain, g1);
			connection.remove(NEAR, SOURCE_LOCATION, origin, g1);
			assertSubjects(connection, merged, List.of());
			assertSubjects(connection, "WHERE { GRAPH <urn:g1> {" + pattern + "} }", List.of());
		} finally {
			repository.shutDown();
		}
	}

	@TestFactory
	Stream<DynamicTest> mergedGeometryLookupsLimitDocumentsAndReturnTheirMatchingGeometries() {
		return Stream.of(CONTAINS, DISTANCE).map(condition -> dynamicTest(condition, () -> {
			var repository = mappedGeometryRepository(new LuceneSail(), new MemoryStore(), new RecordingIndex(),
					TupleFunctionEvaluationMode.NATIVE, new TupleFunctionRegistry(), 1);
			try (var connection = repository.getConnection()) {
				var g1 = Values.iri("urn:g1");
				var g2 = Values.iri("urn:g2");
				var first = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
				var second = Values.literal("POINT(0.001 0)", CoreDatatype.GEO.WKT_LITERAL);
				var outside = Values.literal("POINT(10 10)", CoreDatatype.GEO.WKT_LITERAL);
				// Each graph has a document with two matching geometries and a far geometry in that same document.
				for (var entry : List.of(List.of(NEAR, g1), List.of(FAR, g2))) {
					connection.add(entry.getFirst(), SOURCE_LOCATION, first, entry.getLast());
					connection.add(entry.getFirst(), SOURCE_LOCATION, second, entry.getLast());
					connection.add(entry.getFirst(), SOURCE_LOCATION, outside, entry.getLast());
					connection.add(entry.getFirst(), SOURCE_LOCATION, Values.literal(first.getLabel()),
							entry.getLast());
				}
				String query = PREFIXES + """
						SELECT ?s ?wkt FROM <urn:g1> FROM <urn:g2> WHERE {
							?s <urn:location> ?wkt FILTER(%s)
						}
						""".formatted(condition);
				try (var result = connection.prepareTupleQuery(query).evaluate()) {
					List<BindingSet> rows = result.stream().toList();
					assertEquals(2, rows.size(), rows::toString);
					assertEquals(1, rows.stream().map(row -> row.getValue("s")).distinct().count());
					assertEquals(Set.of(first, second),
							rows.stream().map(row -> row.getValue("wkt")).collect(Collectors.toSet()));
				}
			} finally {
				repository.shutDown();
			}
		}));
	}

