	@Test
	void runtimeDistanceSharesTheDocumentLimitWithNativeLmdb(@TempDir Path dataDir) throws Exception {
		var index = new RecordingIndex();
		var recording = new RecordingDistanceProvider(index);
		var provider = mixedDistanceProvider(recording);
		var registry = TupleFunctionRegistry.getInstance();
		var previous = registry.add(provider);
		try {
			var base = new LmdbStore(dataDir.toFile(), new LmdbStoreConfig().setNativeEvaluationEnabled(true));
			assertTrue(base.isNativeQueryEngineEnabled());
			var repository = mappedGeometryRepository(new LuceneSail(), base, index,
					TupleFunctionEvaluationMode.NATIVE, registry, 1);
			try (var connection = repository.getConnection()) {
				assertSharedRuntimeDistanceLimit(connection, recording);
			} finally {
				repository.shutDown();
			}
		} finally {
			registry.remove(provider);
			previous.ifPresent(registry::add);
		}
	}

