	@Test
	void mergedRuntimeDistanceKeepsOverlappingProviderInvocationsIsolated() throws Exception {
		var index = new RecordingIndex();
		var recording = new RecordingDistanceProvider(index);
		var firstGraph = Values.iri("urn:g1");
		var contexts = new ArrayList<QueryContext>();
		String extensionAttribute = LuceneGeoTest.class.getName();
		var extensionValue = new Object();
		try (var executor = Executors.newSingleThreadExecutor()) {
			var registry = new TupleFunctionRegistry();
			registry.add(new TupleFunction() {
				private CompletableFuture<Void> startFirstLookup;
				private CompletableFuture<? extends CloseableIteration<? extends List<? extends Value>>> firstLookup;

				@Override
				public String getURI() {
					return recording.getURI();
				}

				@Override
				public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory,
						Value... args) {
					var context = QueryContext.getQueryContext();
					contexts.add(context);
					if (!firstGraph.equals(args[args.length - 1])) {
						assertSame(extensionValue, context.getAttribute(extensionAttribute));
						// UNION opens the next graph while the first graph's cursor is still lazy.
						startFirstLookup.complete(null);
						firstLookup.join();
						return recording.evaluate(factory, args);
					}
					context.setAttribute(extensionAttribute, extensionValue);
					var start = new CompletableFuture<Void>();
					startFirstLookup = start;
					var result = start.thenApplyAsync(ignored -> {
						context.begin();
						try {
							return recording.evaluate(factory, args);
						} finally {
							context.end();
						}
					}, executor).orTimeout(10, TimeUnit.SECONDS);
					firstLookup = result;
					return new DelayedIteration<List<? extends Value>>() {
						@Override
						protected CloseableIteration<? extends List<? extends Value>> createIteration() {
							assertSame(context, QueryContext.getQueryContext());
							start.complete(null);
							return result.join();
						}
					};
				}
			});
			var repository = mappedGeometryRepository(new LuceneSail(), new MemoryStore(), index,
					TupleFunctionEvaluationMode.TRIPLE_SOURCE, registry, 1);
			try (var connection = repository.getConnection()) {
				assertSharedRuntimeDistanceLimit(connection, recording);
				assertEquals(4, contexts.stream().distinct().count());
			} finally {
				repository.shutDown();
			}
		}
	}

