	private static void assertProviderCalibration(boolean lazy) throws Exception {
		var index = new RecordingIndex();
		var calibrationMatches = new ArrayList<Integer>();
		var provider = new RecordingDistanceProvider(spec -> {
			var calibration = new DistanceQuerySpec(spec.getFrom(), spec.getUnits(), 1, null, spec.getGeoProperty(),
					"wkt", "s", spec.getContextVar().clone());
			calibrationMatches.add(index.evaluate(calibration).size());
			return index.evaluate(spec);
		});
		var registry = new TupleFunctionRegistry();
		registry.add(new TupleFunction() {
			@Override
			public String getURI() {
				return provider.getURI();
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				if (!lazy) {
					return provider.evaluate(factory, args);
				}
				return new DelayedIteration<List<? extends Value>>() {
					@Override
					protected CloseableIteration<? extends List<? extends Value>> createIteration() {
						return provider.evaluate(factory, args);
					}
				};
			}
		});
		var repository = mappedGeometryRepository(new LuceneSail(), new MemoryStore(), index,
				TupleFunctionEvaluationMode.TRIPLE_SOURCE, registry, 1);
		try (var connection = repository.getConnection()) {
			assertSharedRuntimeDistanceLimit(connection, provider);
			assertEquals(List.of(1, 1, 1, 1), calibrationMatches);
		} finally {
			repository.shutDown();
		}
	}

