	private static void assertSharedRuntimeDistanceLimit(RepositoryConnection connection,
			RecordingDistanceProvider provider) {
		var point = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
		connection.add(NEAR, LOCATION, point, Values.iri("urn:g1"));
		connection.add(FAR, LOCATION, point, Values.iri("urn:g2"));
		String query = PREFIXES + """
				SELECT ?s ?limit FROM <urn:g1> FROM <urn:g2> WHERE {
					%s
					?s <urn:location> ?wkt FILTER(%s)
				} ORDER BY ?limit ?s
				""";
		IRI constantSubject;
		try (var rows = connection.prepareTupleQuery(query.formatted("", DISTANCE)).evaluate()) {
			var subjects = rows.stream().map(row -> row.getValue("s")).toList();
			assertEquals(1, subjects.size());
			constantSubject = (IRI) subjects.getFirst();
		}
		try (var rows = connection.prepareTupleQuery(query.formatted("VALUES ?limit { 1000 2000 }",
				DISTANCE.replace("1000", "?limit"))).evaluate()) {
			assertEquals(List.of(distanceRow(constantSubject, "1000", CoreDatatype.XSD.INTEGER),
					distanceRow(constantSubject, "2000", CoreDatatype.XSD.INTEGER)), rows.stream().toList());
		}
		assertEquals(List.of(1000.0, 1000.0, 2000.0, 2000.0), provider.radii.stream().sorted().toList());
	}

