	private static void assertLegacyProviderGraphArguments(boolean privateNativeRegistry)
			throws Exception {
		var index = new RecordingIndex();
		var functions = new TupleFunctionRegistry();
		var first = Values.iri("urn:g1");
		var second = Values.iri("urn:g2");
		var excluded = Values.iri("urn:g3");
		var point = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
		var subjects = Map.of(first, NEAR, second, FAR, excluded, OTHER);
		var contexts = new ArrayList<Value>();
		functions.add(new TupleFunction() {
			@Override
			public String getURI() {
				return LuceneSailSchema.WITHIN_DISTANCE.stringValue();
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
				Value graph = args.length > 4 ? args[4] : null;
				contexts.add(graph);
				var selected = graph == null ? subjects.values() : List.of(subjects.get(graph));
				return new CloseableIteratorIteration<>(
						selected.stream().map(subject -> List.<Value>of(subject, point)).iterator());
			}
		});
		var repository = mappedGeometryRepository(new LuceneSail(),
				privateNativeRegistry ? baseWithTupleFunctions(functions) : new MemoryStore(), index,
				privateNativeRegistry ? TupleFunctionEvaluationMode.NATIVE : TupleFunctionEvaluationMode.TRIPLE_SOURCE,
				privateNativeRegistry ? new TupleFunctionRegistry() : functions, 1);
		try (var connection = repository.getConnection()) {
			subjects.forEach((graph, subject) -> connection.add(subject, LOCATION, point, graph));
			assertSubjects(connection, """
					FROM <urn:g1> FROM <urn:g2> WHERE {
						VALUES ?limit {1000 2000}
						?s <urn:location> ?wkt FILTER(%s)
					} ORDER BY ?s
					""".formatted(DISTANCE.replace("1000", "?limit")), List.of(FAR, FAR, NEAR, NEAR));
			assertEquals(List.of(first, second, first, second), contexts);
		} finally {
			repository.shutDown();
		}
	}

