	private static SailRepository mappedGeometryRepository(LuceneSail sail, MemoryStore base, RecordingIndex index,
			TupleFunctionEvaluationMode mode, TupleFunctionRegistry registry) throws Exception {
		return mappedGeometryRepository(sail, base, index, mode, registry, -1);
	}

	private static SailRepository mappedGeometryRepository(LuceneSail sail, NotifyingSail base, RecordingIndex index,
			TupleFunctionEvaluationMode mode, TupleFunctionRegistry registry, int maxDocuments) throws Exception {
		Properties parameters = new Properties();
		parameters.setProperty(LuceneSail.LUCENE_RAMDIR_KEY, "true");
		parameters.setProperty(LuceneSail.WKT_FIELDS, LOCATION.stringValue());
		if (maxDocuments >= 0) {
			parameters.setProperty(LuceneSail.MAX_DOCUMENTS_KEY, Integer.toString(maxDocuments));
		}
		index.initialize(parameters);
		sail.setBaseSail(base);
		sail.setLuceneIndex(index);
		sail.setEvaluationMode(mode);
		sail.setTupleFunctionRegistry(registry);
		sail.setParameter(LuceneSail.INDEXEDFIELDS, "index.1=urn:location\nurn\\:sourceLocation=urn:location");
		SailRepository repository = new SailRepository(sail);
		repository.init();
		return repository;
	}

	private static void addGeometries(RepositoryConnection connection, IRI property) {
		connection.add(NEAR, property, Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL));
		connection.add(FAR, property, Values.literal("POINT(10 10)", CoreDatatype.GEO.WKT_LITERAL));
	}

	private static BindingSet distanceRow(IRI subject, String limit, CoreDatatype.XSD datatype) {
		var row = new MapBindingSet();
		row.addBinding("s", subject);
		row.addBinding("limit", Values.literal(limit, datatype));
		return row;
	}

	private static final class RecordingDistanceProvider implements TupleFunction {
		private final Function<DistanceQuerySpec, Collection<BindingSet>> search;
		private final List<Double> radii = new ArrayList<>();

		private RecordingDistanceProvider(RecordingIndex index) {
			this(index::evaluate);
		}

		private RecordingDistanceProvider(Function<DistanceQuerySpec, Collection<BindingSet>> search) {
			this.search = search;
		}

		@Override
		public String getURI() {
			return LuceneSailSchema.WITHIN_DISTANCE.stringValue();
		}

		@Override
		public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory factory, Value... args) {
			var origin = (Literal) args[0];
			var radius = (Literal) args[1];
			var datatype = radius.getCoreDatatype().asXSDDatatypeOrNull();
			assertTrue(datatype.isNumericDatatype() && XMLDatatypeUtil.isValidValue(radius.getLabel(), datatype));
			double distance = radius.doubleValue();
			assertTrue(Double.isFinite(distance) && distance >= 0);
			radii.add(distance);
			Var context = args.length == 5 ? Var.of("context", (Resource) args[4], true, true) : null;
			var spec = new DistanceQuerySpec(origin, (IRI) args[2], distance, null, (IRI) args[3], "wkt", "s",
					context);
			List<List<Value>> matches = search.apply(spec)
					.stream()
					.map(row -> List.of(row.getValue("s"), row.getValue("wkt")))
					.toList();
			return new CloseableIteratorIteration<>(matches.iterator());
		}
	}

	@TestFactory
	Stream<DynamicTest> geometryPredicatesKeepVariableResults() {
		BindingSet location = row(NEAR, LOCATION);
		BindingSet other = row(NEAR, OTHER);
		var cases = List.of(
				new GeometryCase("BIND", "BIND(<urn:location> AS ?p) ?s ?p ?wkt FILTER(%s)", List.of(location)),
				new GeometryCase("VALUES", "VALUES ?p { <urn:location> } ?s ?p ?wkt FILTER(%s)", List.of(location)),
				new GeometryCase("duplicate VALUES",
						"VALUES ?p { <urn:location> <urn:location> } ?s ?p ?wkt FILTER(%s)",
						List.of(location, location)),
				new GeometryCase("different VALUES", "VALUES ?p { <urn:location> <urn:other> } ?s ?p ?wkt FILTER(%s)",
						List.of(location, other)),
				new GeometryCase("unbound predicate", "?s ?p ?wkt FILTER(%s)", List.of(location, other)),
				new GeometryCase("unmatched OPTIONAL",
						"VALUES ?p { <urn:location> } OPTIONAL { VALUES ?s { <urn:missing> } ?s ?p ?wkt FILTER(%s) }",
						List.of(row(null, LOCATION))));
		return Stream.of(TupleFunctionEvaluationMode.values())
				.flatMap(mode -> Stream.of(DISTANCE, INTERSECTS)
						.flatMap(filter -> cases.stream()
								.map(test -> dynamicTest(
										mode + " " + test.name() + " " + filter,
										() -> assertGeometryRows(mode, test.pattern().formatted(filter),
												test.expected())))));
	}

	@TestFactory
	Stream<DynamicTest> geometryFiltersApplyAcrossUnionAndOptional() {
		var cases = List.of(
				new GeometryCase("UNION", """
						{ ?s <urn:location> ?wkt } UNION { VALUES ?s { <urn:missing> } }
						FILTER(%s)
						""", List.of(row(NEAR, LOCATION))),
				new GeometryCase("OPTIONAL", """
						VALUES ?s { <urn:near> <urn:missing> }
						OPTIONAL { ?s <urn:location> ?wkt }
						FILTER(%s)
						""", List.of(row(NEAR, LOCATION))),
				new GeometryCase("nested UNION and OPTIONAL", """
						{ ?s <urn:location> ?wkt }
						UNION { VALUES ?s { <urn:missing> } OPTIONAL { ?s <urn:location> ?wkt } }
						FILTER(%s)
						""", List.of(row(NEAR, LOCATION))));
		return Stream.of("geof:distance(?origin, ?wkt, uom:metre) < 1000", "geof:sfIntersects(?origin, ?wkt)")
				.flatMap(filter -> cases.stream()
						.flatMap(test -> Stream.of(TupleFunctionEvaluationMode.values())
								.map(mode -> dynamicTest(
										mode + " " + test.name() + " " + filter,
										() -> assertGeometryRows(mode, ORIGIN_VALUES + test.pattern().formatted(filter),
												test.expected())))));
	}

	@TestFactory
	Stream<DynamicTest> distanceFiltersKeepInvalidValuesThresholdsInSparql() {
		var cases = List.of(
				new GeometryCase("nonnumeric string", "VALUES ?limit { 'not a number' } FILTER(%s < ?limit)",
						List.of()),
				new GeometryCase("numeric string", "VALUES ?limit { '1000' } FILTER(%s < ?limit)", List.of()),
				new GeometryCase("inline numeric string", "FILTER(%s < '1000')", List.of()),
				new GeometryCase("malformed typed literal", "VALUES ?limit { 'bad'^^xsd:double } FILTER(%s < ?limit)",
						List.of()),
				new GeometryCase("NaN", "VALUES ?limit { 'NaN'^^xsd:double } FILTER(%s < ?limit)", List.of()),
				new GeometryCase("negative", "VALUES ?limit { -1000 } FILTER(%s < ?limit)", List.of()),
				new GeometryCase("IRI", "VALUES ?limit { <urn:invalid> } FILTER(%s < ?limit)", List.of()),
				new GeometryCase("mixed VALUES", "VALUES ?limit { 'bad' UNDEF 1000 } FILTER(%s < ?limit)",
						List.of(row(NEAR, LOCATION))));
		return cases.stream()
				.flatMap(test -> Stream.of(TupleFunctionEvaluationMode.values())
						.map(mode -> dynamicTest(
								mode + " " + test.name(),
								() -> assertGeometryRows(mode, ORIGIN_VALUES + "?s <urn:location> ?wkt "
										+ test.pattern().formatted("geof:distance(?origin, ?wkt, uom:metre)"),
										test.expected()))));
	}

	private static void assertGeometryRows(TupleFunctionEvaluationMode mode, String pattern,
			List<BindingSet> expected) {
		LuceneSail sail = new LuceneSail();
		sail.setBaseSail(new MemoryStore());
		sail.setParameter(LuceneSail.LUCENE_RAMDIR_KEY, "true");
		sail.setParameter(LuceneSail.WKT_FIELDS, LOCATION.stringValue());
		sail.setEvaluationMode(mode);
		SailRepository repository = new SailRepository(sail);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				var origin = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
				connection.add(NEAR, LOCATION, origin);
				connection.add(NEAR, OTHER, origin);
				connection.add(Values.iri("urn:far"), LOCATION,
						Values.literal("POINT(10 10)", CoreDatatype.GEO.WKT_LITERAL));

				String query = PREFIXES + "SELECT ?s ?p WHERE { " + pattern + " } ORDER BY ?p";
				try (var rows = connection.prepareTupleQuery(query).evaluate()) {
					assertEquals(List.of("s", "p"), rows.getBindingNames());
					assertEquals(expected, rows.stream().toList());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private record GeometryCase(String name, String pattern, List<BindingSet> expected) {
	}

	private static MapBindingSet row(IRI subject, IRI predicate) {
		MapBindingSet row = new MapBindingSet();
		if (subject != null) {
			row.addBinding("s", subject);
		}
		row.addBinding("p", predicate);
		return row;
	}

	@Test
	void directDistanceStillUsesTheIndex() throws Exception {
		RecordingIndex index = new RecordingIndex();
		Properties parameters = new Properties();
		parameters.setProperty(LuceneSail.LUCENE_RAMDIR_KEY, "true");
		parameters.setProperty(LuceneSail.WKT_FIELDS, LOCATION.stringValue());
		index.initialize(parameters);
		LuceneSail sail = new LuceneSail();
		sail.setBaseSail(new MemoryStore());
		sail.setLuceneIndex(index);
		SailRepository repository = new SailRepository(sail);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.add(NEAR, LOCATION, Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL));
				try (var rows = connection.prepareTupleQuery(
						PREFIXES + "SELECT ?s WHERE { ?s <urn:location> ?wkt FILTER(" + DISTANCE + ") }")
						.evaluate()) {
					assertEquals(List.of(NEAR), rows.stream().map(row -> row.getValue("s")).toList());
				}
				assertEquals(1, index.distanceQueries);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static class RecordingIndex extends LuceneIndex {
		private int distanceQueries;

		@Override
		protected Iterable<? extends DocumentDistance> geoQuery(IRI geoProperty, Point point, IRI units,
				double distance, String distanceVar, Var contextVar) throws IOException {
			distanceQueries++;
			return super.geoQuery(geoProperty, point, units, distance, distanceVar, contextVar);
		}
	}

	@Test
	void tripleSourceReusesTheWorkingQueryTree() {
		LuceneSail sail = new LuceneSail();
		sail.setBaseSail(new MemoryStore());
		sail.setParameter(LuceneSail.LUCENE_RAMDIR_KEY, "true");
		sail.setEvaluationMode(TupleFunctionEvaluationMode.TRIPLE_SOURCE);
		SailRepository repository = new SailRepository(sail);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.add(NEAR, LOCATION, Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL));
			}
			var root = new CountingRoot(new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")));
			try (var connection = sail.getConnection()) {
				var rows = QueryResults.asList(connection.evaluate(root, null, EmptyBindingSet.getInstance(), true));
				assertEquals(List.of(NEAR), rows.stream().map(row -> row.getValue("s")).toList());
			}
			assertEquals(1, root.copies.get());
		} finally {
			repository.shutDown();
		}
	}

	private static final class CountingRoot extends QueryRoot {
		private final AtomicInteger copies = new AtomicInteger();

		private CountingRoot(TupleExpr arg) {
			super(arg);
		}

		@Override
		public QueryRoot clone() {
			copies.incrementAndGet();
			return super.clone();
		}
	}

	@Test
	void tripleSourcePreservesInheritedStatementPatternBindings() {
		LuceneSail sail = new LuceneSail();
		sail.setBaseSail(new MemoryStore());
		sail.setParameter(LuceneSail.LUCENE_RAMDIR_KEY, "true");
		sail.setEvaluationMode(TupleFunctionEvaluationMode.TRIPLE_SOURCE);
		SailRepository repository = new SailRepository(sail);
		try {
			repository.init();
			var origin = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
			try (var connection = repository.getConnection()) {
				connection.add(NEAR, LOCATION, origin);
			}
			var duplicates = new BindingSetAssignment();
			duplicates.setBindingSets(List.of(EmptyBindingSet.getInstance(), EmptyBindingSet.getInstance()));
			var pattern = new InheritedStatementPattern();
			var root = new QueryRoot(new Join(duplicates, pattern));
			try (var connection = sail.getConnection()) {
				var bindings = new MapBindingSet();
				bindings.addBinding("s", NEAR);
				var expected = row(NEAR, LOCATION);
				expected.addBinding("o", origin);
				assertEquals(List.of(expected, expected),
						QueryResults.asList(connection.evaluate(root, null, bindings, true)));

				bindings.setBinding("s", Values.iri("urn:missing"));
				assertEquals(List.of(), QueryResults.asList(connection.evaluate(root, null, bindings, true)));

				bindings.clear();
				bindings.addBinding("unused", NEAR);
				assertEquals(List.of(expected, expected),
						QueryResults.asList(connection.evaluate(root, null, bindings, true)));
			}
			assertFalse(pattern.getSubjectVar().hasValue());
		} finally {
			repository.shutDown();
		}
	}

	private static final class InheritedStatementPattern extends StatementPattern {
		private InheritedStatementPattern() {
			super(Var.of("s"), Var.of("p"), Var.of("o"));
		}
	}

	@Test
	public void projectedDistanceParametersSurviveSearchLoweringInEveryMode() {
		for (var mode : TupleFunctionEvaluationMode.values()) {
			LuceneSail sail = new LuceneSail();
			sail.setParameter(LuceneSail.LUCENE_RAMDIR_KEY, "true");
			sail.setParameter(LuceneSail.WKT_FIELDS, "urn:location");
			sail.setEvaluationMode(mode);
			sail.setBaseSail(new MemoryStore());
			SailRepository repository = new SailRepository(sail);
			try {
				repository.init();
				try (var connection = repository.getConnection()) {
					var origin = Values.literal("POINT(0 0)", CoreDatatype.GEO.WKT_LITERAL);
					var units = Values.iri("http://www.opengis.net/def/uom/OGC/1.0/metre");
					connection.add(Values.iri("urn:near"), Values.iri("urn:location"), origin);
					connection.add(Values.iri("urn:far"), Values.iri("urn:location"),
							Values.literal("POINT(10 10)", CoreDatatype.GEO.WKT_LITERAL));
					var query = connection.prepareTupleQuery("SELECT ?s ?from ?units ?limit WHERE { "
							+ "?s <urn:location> ?location "
							+ "BIND(<http://www.opengis.net/def/function/geosparql/distance>"
							+ "(?from, ?location, ?units) AS ?distance) FILTER(?distance < ?limit) }");
					query.setBinding("from", origin);
					query.setBinding("units", units);
					query.setBinding("limit", Values.literal(1000));
					try (var result = query.evaluate()) {
						assertTrue(result.hasNext(), "mode=" + mode);
						var row = result.next();
						assertEquals(Values.iri("urn:near"), row.getValue("s"), "mode=" + mode);
						assertEquals(origin, row.getValue("from"), "mode=" + mode);
						assertEquals(units, row.getValue("units"), "mode=" + mode);
						assertEquals(Values.literal(1000), row.getValue("limit"), "mode=" + mode);
						assertFalse(result.hasNext(), "mode=" + mode);
					}
				}
			} finally {
				repository.shutDown();
			}
		}
	}

	@Test
	public void geoFailTest() {
		MemoryStore store = new MemoryStore();
		LuceneSail lucene = new LuceneSail();
		lucene.setParameter(LuceneSail.LUCENE_RAMDIR_KEY, "true");
		lucene.setParameter(LuceneSail.WKT_FIELDS, "https://example.org/#location");
		lucene.setBaseSail(store);
		SailRepository repo = new SailRepository(lucene);
		try {
			repo.init();

			Repositories.consume(repo, conn -> {
				try {
					conn.add(new StringReader(
							"@prefix ex: <https://example.org/#> ."
									// point in
									+ "ex:s ex:location \"POINT(9.6929555 45.6762274)\"^^<http://www.opengis.net/ont/geosparql#wktLiteral> ."
					// point out
									+ "ex:s ex:location \"POINT(9.18457 45.466873)\"^^<http://www.opengis.net/ont/geosparql#wktLiteral> ."
					), "https://example.org/#", RDFFormat.TURTLE);
				} catch (IOException e) {
					throw new AssertionError(e);
				}
			});

			lucene.reindex();

			// a random polygon of Milan
			// POLYGON((9.000892639160158 45.3796432523812,9.381294250488283 45.3796432523812,9.381294250488283
			// 45.55420812072298,9.000892639160158 45.55420812072298,9.000892639160158 45.3796432523812))
			Repositories.consumeNoTransaction(repo, conn -> {
				try (TupleQueryResult res = conn.prepareTupleQuery(
						"PREFIX ex: <https://example.org/#> "
								+ "SELECT * { "
								+ "  ?s ex:location ?loc "
								+ "  FILTER (<http://www.opengis.net/def/function/geosparql/ehContains>(\"POLYGON((9.000892639160158 45.3796432523812,9.381294250488283 45.3796432523812,9.381294250488283 45.55420812072298,9.000892639160158 45.55420812072298,9.000892639160158 45.3796432523812))\"^^<http://www.opengis.net/ont/geosparql#wktLiteral>, ?loc)) "
								+ "} "
				).evaluate()) {
					assertTrue(res.hasNext(), "missing good value");
					BindingSet next = res.next();
					assertEquals(Values.iri("https://example.org/#s"), next.getValue("s"));
					assertEquals(Values.literal("POINT(9.18457 45.466873)", CoreDatatype.GEO.WKT_LITERAL),
							next.getValue("loc"));
					assertFalse(res.hasNext(), "more value(s) :"
							+ res.stream().map(Object::toString).collect(Collectors.joining("\n", "\n", "")));
				}
			});

		} finally {
			repo.shutDown();
		}

	}
